			<p class="dialog-message">
				{@html t('dialog.confirm.message', { model: diskSelectionData.disk?.model || 'Unknown' })}
			</p>
			<!-- svelte-ignore css_unused_selector -->
			<div class="dialog-actions">
				<button type="button" class="btn-cancel" onclick={() => showConfirmDialog.value = false}>
